'use client'

import {
  cloneElement,
  forwardRef,
  isValidElement,
  useCallback,
  useId,
  useState,
  type ReactNode,
} from 'react'
import { motion, useReducedMotion } from 'motion/react'
import { cn } from '@/lib/utils'
import { springs } from '@/lib/motion-tokens'

export type CheckedState = boolean | 'indeterminate'

export interface CheckboxProps {
  id?: string
  checked?: CheckedState
  defaultChecked?: boolean
  onCheckedChange?: (checked: CheckedState) => void
  name?: string
  disabled?: boolean
  required?: boolean
  'aria-invalid'?: boolean | 'true' | 'false' | 'grammar' | 'spelling'
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-describedby'?: string
  className?: string
  value?: string
}

export interface CheckboxFieldProps {
  label: string
  description?: string
  strikeThrough?: boolean
  className?: string
  children: ReactNode
}

function useControlledChecked(
  controlledValue: CheckedState | undefined,
  defaultValue: boolean | undefined,
  onChange: ((checked: CheckedState) => void) | undefined,
): [CheckedState, (next: CheckedState) => void] {
  const [internal, setInternal] = useState<CheckedState>(defaultValue ?? false)
  const isControlled = controlledValue !== undefined
  const value = isControlled ? controlledValue : internal

  const setValue = useCallback(
    (next: CheckedState) => {
      if (!isControlled) setInternal(next)
      onChange?.(next)
    },
    [isControlled, onChange],
  )

  return [value, setValue]
}

const CHECK_PATH = 'M3.5 8.5L7 12L12.5 5.5'
const DASH_PATH = 'M4 8L12 8'

function CheckGlyph({ state, animate }: { state: CheckedState; animate: boolean }) {
  const reduceMotion = useReducedMotion()
  const isChecked = state === true
  const isIndeterminate = state === 'indeterminate'
  const shouldShow = isChecked || isIndeterminate

  if (!shouldShow) return null

  const path = isIndeterminate ? DASH_PATH : CHECK_PATH
  const shouldAnimate = animate && !reduceMotion

  return (
    <svg viewBox="0 0 16 16" fill="none" className="absolute inset-0 size-full" aria-hidden="true">
      <motion.path
        d={path}
        stroke="currentColor"
        strokeWidth={2}
        strokeLinecap="round"
        strokeLinejoin="round"
        initial={shouldAnimate ? { pathLength: 0, opacity: 0 } : { pathLength: 1, opacity: 1 }}
        animate={{ pathLength: 1, opacity: 1 }}
        exit={shouldAnimate ? { pathLength: 0, opacity: 0 } : undefined}
        transition={shouldAnimate ? springs.fast : { duration: 0 }}
      />
    </svg>
  )
}

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(
  (
    {
      id,
      checked: controlledChecked,
      defaultChecked,
      onCheckedChange,
      name,
      disabled = false,
      required = false,
      'aria-invalid': ariaInvalid,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledBy,
      'aria-describedby': ariaDescribedBy,
      className,
      value = 'on',
    },
    forwardedRef,
  ) => {
    const [checkedState, setCheckedState] = useControlledChecked(
      controlledChecked,
      defaultChecked,
      onCheckedChange,
    )

    const [toggleCount, setToggleCount] = useState(0)

    const isChecked = checkedState === true
    const isIndeterminate = checkedState === 'indeterminate'

    const ariaCheckedValue = isIndeterminate ? 'mixed' : isChecked

    const handleClick = useCallback(() => {
      if (disabled) return
      const next: CheckedState = isIndeterminate ? true : !isChecked
      setCheckedState(next)
      setToggleCount((c) => c + 1)
    }, [disabled, isIndeterminate, isChecked, setCheckedState])

    const handleKeyDown = useCallback(
      (e: React.KeyboardEvent<HTMLButtonElement>) => {
        if (e.key === ' ' || e.key === 'Enter') {
          e.preventDefault()
          handleClick()
        }
      },
      [handleClick],
    )

    const handlePointerDown = useCallback((e: React.PointerEvent<HTMLButtonElement>) => {
      e.preventDefault()
    }, [])

    return (
      <>
        <button
          id={id}
          type="button"
          role="checkbox"
          aria-checked={ariaCheckedValue}
          aria-label={ariaLabel}
          aria-labelledby={ariaLabelledBy}
          aria-invalid={ariaInvalid}
          aria-describedby={ariaDescribedBy}
          aria-disabled={disabled || undefined}
          disabled={disabled}
          aria-required={required || undefined}
          onClick={handleClick}
          onKeyDown={handleKeyDown}
          onPointerDown={handlePointerDown}
          className={cn(
            'relative inline-flex size-5 shrink-0 items-center justify-center rounded-[5px] supports-[corner-shape:squircle]:corner-squircle',
            'border border-(--color-border)',
            'transition-colors duration-(--motion-dur-fast) ease-(--motion-ease-out) motion-reduce:transition-none',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-offset-1 focus-visible:ring-offset-(--color-bg)',
            'disabled:cursor-not-allowed disabled:opacity-50',
            (isChecked || isIndeterminate) &&
              'border-transparent bg-(--color-fg) text-(--color-bg)',
            !(isChecked || isIndeterminate) && 'bg-(--color-bg)',
            ariaInvalid && 'border-destructive',
            className,
          )}
        >
          <CheckGlyph state={checkedState} animate={toggleCount > 0} />
        </button>
        <input
          ref={forwardedRef}
          type="checkbox"
          name={name}
          value={value}
          checked={isChecked}
          disabled={disabled}
          required={required}
          aria-hidden="true"
          tabIndex={-1}
          onChange={() => {}}
          className="pointer-events-none absolute size-0 opacity-0"
          style={{ position: 'absolute', width: 0, height: 0 }}
        />
      </>
    )
  },
)
Checkbox.displayName = 'Checkbox'

export function CheckboxField({
  label,
  description,
  strikeThrough = false,
  className,
  children,
}: CheckboxFieldProps) {
  const generatedId = useId()
  const labelId = `${generatedId}-label`
  const descriptionId = description ? `${generatedId}-description` : undefined
  const checkbox = isValidElement<CheckboxProps>(children) ? children : null
  const controlId = checkbox?.props.id ?? `${generatedId}-control`
  const describedBy = [checkbox?.props['aria-describedby'], descriptionId].filter(Boolean).join(' ')
  const control = checkbox
    ? cloneElement(checkbox, {
        id: controlId,
        'aria-labelledby':
          checkbox.props['aria-labelledby'] ?? (checkbox.props['aria-label'] ? undefined : labelId),
        'aria-describedby': describedBy || undefined,
      })
    : children

  const isChecked = checkbox?.props.checked === true
  const reduceMotion = useReducedMotion()

  return (
    <div className={cn('flex min-h-11 items-start gap-3', className)}>
      {control}
      <div className="flex flex-col gap-0.5">
        <label
          id={labelId}
          htmlFor={controlId}
          className="cursor-pointer text-base font-medium leading-tight select-none"
        >
          {strikeThrough ? (
            <span
              className={cn(
                'relative inline-block transition-colors duration-(--motion-dur-base) ease-(--motion-ease-out) motion-reduce:transition-none',
                isChecked ? 'text-(--color-muted)' : 'text-(--color-fg)',
              )}
            >
              {label}
              <motion.span
                aria-hidden="true"
                className="absolute left-0 right-0 top-1/2 h-px bg-current motion-reduce:transition-none"
                style={{ transformOrigin: 'left' }}
                initial={false}
                animate={{ scaleX: isChecked ? 1 : 0 }}
                transition={reduceMotion ? { duration: 0 } : springs.settle}
              />
            </span>
          ) : (
            <span className="text-(--color-fg)">{label}</span>
          )}
        </label>
        {description && (
          <p id={descriptionId} className="text-sm leading-snug text-(--color-muted)">
            {description}
          </p>
        )}
      </div>
    </div>
  )
}

export function CheckboxPreview() {
  const [todoChecked, setTodoChecked] = useState(false)

  return (
    <div className="flex flex-col gap-4 p-8">
      <Checkbox defaultChecked />
      <Checkbox />
      <Checkbox checked="indeterminate" />
      <Checkbox disabled defaultChecked />
      <CheckboxField label="Buy groceries" strikeThrough>
        <Checkbox checked={todoChecked} onCheckedChange={(next) => setTodoChecked(next === true)} />
      </CheckboxField>
    </div>
  )
}

export const durations = {
  instant: '50ms',
  fast: '120ms',
  base: '200ms',
  slow: '320ms',
} as const

export const easings = {
  out: 'cubic-bezier(0.22, 1, 0.36, 1)',
  inOut: 'cubic-bezier(0.65, 0, 0.35, 1)',
} as const

export const springs = {
  fast: { type: 'spring', stiffness: 400, damping: 30, mass: 0.8 },
  press: { type: 'spring', stiffness: 700, damping: 32, mass: 1 },
  moderate: { type: 'spring', stiffness: 300, damping: 24, mass: 1 },
  settle: { type: 'spring', stiffness: 260, damping: 26, mass: 1 },
} as const

'use client'

const MUTE_KEY = 'sound-muted'
const MUTE_EVENT = 'sound-mute-change'

let muted = false
if (typeof window !== 'undefined') {
  try {
    muted = localStorage.getItem(MUTE_KEY) === '1'
  } catch {}
}

export function isSoundMuted(): boolean {
  return muted
}

export function setSoundMuted(value: boolean) {
  muted = value
  if (typeof window !== 'undefined') {
    try {
      localStorage.setItem(MUTE_KEY, value ? '1' : '0')
    } catch {}
    window.dispatchEvent(new CustomEvent(MUTE_EVENT))
  }
}

export function toggleSoundMuted(): boolean {
  setSoundMuted(!muted)
  return muted
}

export function subscribeSoundMuted(callback: () => void) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener(MUTE_EVENT, callback)
  const onStorage = (e: StorageEvent) => {
    if (e.key === MUTE_KEY) callback()
  }
  window.addEventListener('storage', onStorage)
  return () => {
    window.removeEventListener(MUTE_EVENT, callback)
    window.removeEventListener('storage', onStorage)
  }
}

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

if (typeof window !== 'undefined') {
  const unlock = () => {
    initAudio()
    window.removeEventListener('pointerdown', unlock)
    window.removeEventListener('keydown', unlock)
    window.removeEventListener('touchstart', unlock)
  }
  window.addEventListener('pointerdown', unlock, { passive: true })
  window.addEventListener('keydown', unlock, { passive: true })
  window.addEventListener('touchstart', unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

export function playHoverSound(volume = 0.12, pitch = 1.2) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {}
}

export function playClickSound(volume = 0.2, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'triangle'
    osc.frequency.setValueAtTime(850 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(160 * pitch, now + 0.02)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.02)
  } catch {}
}

export function playTickSound(volume = 0.1, pitch = 1.5) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1800 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(450 * pitch, now + 0.01)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.01)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.01)
  } catch {}
}

export function playBounceSound(volume = 0.3, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(260 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(650 * pitch, now + 0.04)
    osc.frequency.exponentialRampToValueAtTime(190 * pitch, now + 0.14)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.14)

    const subOsc = ctx.createOscillator()
    const subGain = ctx.createGain()

    subOsc.type = 'triangle'
    subOsc.frequency.setValueAtTime(420 * pitch, now)
    subOsc.frequency.exponentialRampToValueAtTime(120 * pitch, now + 0.05)

    subGain.gain.setValueAtTime(volume * 0.7, now)
    subGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05)

    subOsc.connect(subGain)
    subGain.connect(ctx.destination)

    subOsc.start(now)
    subOsc.stop(now + 0.05)
  } catch {}
}
